function escalationErrors(values) {
  // Each field judged alone, so the conditional rules are wrong.
  const errors = [];
  if (values.reason === '') errors.push('reason');
  if (values.detail === '') errors.push('detail');
  if (values.phone === '') errors.push('phone');
  return errors;
